-- Phase 03.2Y: Enterprise Data Platform

CREATE TABLE IF NOT EXISTS data_source (id UUID PRIMARY KEY, tenant_id UUID, name VARCHAR, type VARCHAR, config JSONB, status VARCHAR, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS data_connector (id UUID PRIMARY KEY, tenant_id UUID, source_id UUID, target_id UUID, config JSONB, status VARCHAR, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS data_pipeline (id UUID PRIMARY KEY, tenant_id UUID, name VARCHAR, description TEXT, config JSONB, status VARCHAR, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS pipeline_execution (id UUID PRIMARY KEY, tenant_id UUID, pipeline_id UUID, start_time TIMESTAMP WITH TIME ZONE, end_time TIMESTAMP WITH TIME ZONE, status VARCHAR, logs JSONB, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS pipeline_schedule (id UUID PRIMARY KEY, tenant_id UUID, pipeline_id UUID, cron_expression VARCHAR, is_active BOOLEAN, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS etl_job (id UUID PRIMARY KEY, tenant_id UUID, pipeline_id UUID, step_name VARCHAR, status VARCHAR, metrics JSONB, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS elt_job (id UUID PRIMARY KEY, tenant_id UUID, pipeline_id UUID, step_name VARCHAR, status VARCHAR, metrics JSONB, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS data_lake (id UUID PRIMARY KEY, tenant_id UUID, name VARCHAR, storage_provider VARCHAR, config JSONB, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS lake_object (id UUID PRIMARY KEY, tenant_id UUID, lake_id UUID, path VARCHAR, size_bytes BIGINT, metadata JSONB, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS warehouse_dataset (id UUID PRIMARY KEY, tenant_id UUID, name VARCHAR, description TEXT, schema_definition JSONB, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS warehouse_table (id UUID PRIMARY KEY, tenant_id UUID, dataset_id UUID, table_name VARCHAR, schema_definition JSONB, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS warehouse_snapshot (id UUID PRIMARY KEY, tenant_id UUID, table_id UUID, snapshot_date TIMESTAMP WITH TIME ZONE, row_count BIGINT, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS metadata_catalog (id UUID PRIMARY KEY, tenant_id UUID, name VARCHAR, description TEXT, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS metadata_attribute (id UUID PRIMARY KEY, tenant_id UUID, catalog_id UUID, key VARCHAR, value TEXT, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS data_dictionary (id UUID PRIMARY KEY, tenant_id UUID, table_id UUID, column_name VARCHAR, data_type VARCHAR, description TEXT, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
