CREATE TABLE IF NOT EXISTS data_validation_result (id UUID PRIMARY KEY, tenant_id UUID, rule_id UUID, execution_time TIMESTAMP WITH TIME ZONE, passed BOOLEAN, details JSONB, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS data_profile (id UUID PRIMARY KEY, tenant_id UUID, dataset_id UUID, profiling_data JSONB, generated_at TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS data_lineage (id UUID PRIMARY KEY, tenant_id UUID, source_node VARCHAR, target_node VARCHAR, transformation_logic TEXT, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS feature_store (id UUID PRIMARY KEY, tenant_id UUID, name VARCHAR, description TEXT, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS feature_definition (id UUID PRIMARY KEY, tenant_id UUID, store_id UUID, feature_name VARCHAR, data_type VARCHAR, calculation_logic TEXT, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS ml_dataset (id UUID PRIMARY KEY, tenant_id UUID, name VARCHAR, version_number VARCHAR, features JSONB, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS training_job (id UUID PRIMARY KEY, tenant_id UUID, dataset_id UUID, model_name VARCHAR, status VARCHAR, metrics JSONB, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS trained_model (id UUID PRIMARY KEY, tenant_id UUID, job_id UUID, model_path VARCHAR, accuracy NUMERIC, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS model_registry (id UUID PRIMARY KEY, tenant_id UUID, name VARCHAR, description TEXT, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS model_version (id UUID PRIMARY KEY, tenant_id UUID, registry_id UUID, version_number VARCHAR, model_id UUID, status VARCHAR, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS model_deployment (id UUID PRIMARY KEY, tenant_id UUID, version_id UUID, endpoint_url VARCHAR, status VARCHAR, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS embedding_collection (id UUID PRIMARY KEY, tenant_id UUID, name VARCHAR, dimension INT, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS embedding_vector (id UUID PRIMARY KEY, tenant_id UUID, collection_id UUID, vector JSONB, metadata JSONB, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS vector_index (id UUID PRIMARY KEY, tenant_id UUID, collection_id UUID, index_type VARCHAR, status VARCHAR, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS semantic_document (id UUID PRIMARY KEY, tenant_id UUID, collection_id UUID, document_text TEXT, metadata JSONB, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
