CREATE TABLE IF NOT EXISTS knowledge_edge (id UUID PRIMARY KEY, tenant_id UUID, graph_id UUID, source_node_id UUID, target_node_id UUID, relationship VARCHAR, properties JSONB, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS graph_relationship (id UUID PRIMARY KEY, tenant_id UUID, name VARCHAR, properties_schema JSONB, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS ai_dataset (id UUID PRIMARY KEY, tenant_id UUID, name VARCHAR, purpose VARCHAR, records_count INT, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS ai_training_log (id UUID PRIMARY KEY, tenant_id UUID, dataset_id UUID, epoch INT, loss NUMERIC, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS streaming_event (id UUID PRIMARY KEY, tenant_id UUID, stream_id UUID, event_type VARCHAR, payload JSONB, timestamp TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS event_stream (id UUID PRIMARY KEY, tenant_id UUID, name VARCHAR, topic_name VARCHAR, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS cdc_log (id UUID PRIMARY KEY, tenant_id UUID, table_name VARCHAR, operation VARCHAR, old_data JSONB, new_data JSONB, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS event_replay (id UUID PRIMARY KEY, tenant_id UUID, stream_id UUID, start_time TIMESTAMP WITH TIME ZONE, end_time TIMESTAMP WITH TIME ZONE, status VARCHAR, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS lakehouse_object (id UUID PRIMARY KEY, tenant_id UUID, name VARCHAR, format VARCHAR, location VARCHAR, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS retention_policy (id UUID PRIMARY KEY, tenant_id UUID, entity_type VARCHAR, retention_days INT, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS archive_policy (id UUID PRIMARY KEY, tenant_id UUID, entity_type VARCHAR, archive_after_days INT, storage_tier VARCHAR, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), deleted_at TIMESTAMP WITH TIME ZONE, created_by UUID, updated_by UUID, version INT DEFAULT 1, status_db VARCHAR(50) DEFAULT 'ACTIVE');

ALTER TABLE data_pipeline ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation_data_pipeline ON data_pipeline;
CREATE POLICY tenant_isolation_data_pipeline ON data_pipeline FOR ALL USING (tenant_id = current_setting('app.current_tenant')::UUID);

ALTER TABLE warehouse_dataset ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation_warehouse_dataset ON warehouse_dataset;
CREATE POLICY tenant_isolation_warehouse_dataset ON warehouse_dataset FOR ALL USING (tenant_id = current_setting('app.current_tenant')::UUID);
